// @ts-check
import { TypeSerializer } from './TypeSerializer.js'
import { BufferWriter } from './BufferWriter.js'
import { ReferencesCache } from '../referenceCache/ReferencesCache.js'
import { Command } from '../../utils/Command.js'
import { CommandType } from '../../utils/CommandType.js'
import { RuntimeName } from '../../utils/RuntimeName.js'
import { TypesHandler } from '../../utils/TypesHandler.js'

/**
 * @typedef {import('../../utils/connectionData/IConnectionData.js').IConnectionData} IConnectionData
 * @typedef {import('./BufferWriter.js').BufferWriterState} BufferWriterState
 */
class CommandSerializer {
    /** @type {Uint8Array} */
    static EmptyConnectionData = new Uint8Array(7)

    constructor() {
        throw new Error('CommandSerializer is a static utility class and cannot be instantiated')
    }

    /**
     * @param {Command} rootCommand
     * @param {IConnectionData} connectionData
     * @param {number} runtimeVersion
     * @returns {Uint8Array}
     */
    static serialize(rootCommand, connectionData, runtimeVersion = 0) {
        const writer = BufferWriter.create(256)

        BufferWriter.writeUInt8(writer, rootCommand.runtimeName)
        BufferWriter.writeUInt8(writer, runtimeVersion)

        if (connectionData) {
            BufferWriter.writeBytes(writer, Uint8Array.from(connectionData.serializeConnectionData()))
        } else {
            BufferWriter.writeBytes(writer, CommandSerializer.EmptyConnectionData)
        }

        BufferWriter.writeUInt8(writer, RuntimeName.Nodejs)
        BufferWriter.writeUInt8(writer, rootCommand.commandType)

        CommandSerializer.serializeRecursively(rootCommand, writer)

        return BufferWriter.toUint8Array(writer)
    }

    /**
     * @param {Command} command
     * @param {BufferWriterState} writer
     */
    static serializeRecursively(command, writer) {
        for (const item of command.payload) {
            if (item instanceof Command) {
                TypeSerializer.writeCommandHeader(writer, item)
                CommandSerializer.serializeRecursively(item, writer)
            } else if (TypesHandler.isPrimitiveOrNullOrUndefined(item)) {
                TypeSerializer.writePrimitive(writer, item)
            } else {
                const cachedReference = ReferencesCache.getInstance().cacheReference(item)
                const refCommand = new Command(RuntimeName.Nodejs, CommandType.Reference, [cachedReference])
                TypeSerializer.writeCommandHeader(writer, refCommand)
                CommandSerializer.serializeRecursively(refCommand, writer)
            }
        }
    }
}

export { CommandSerializer }
